window.HOEREN_TESTS[98] = {"id":"im-sprachcafe","name":"Im Sprachcafé","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Gäste: Willkommen im Sprachcafé. Hier treffen sich Menschen aus vielen Ländern, um Sprachen zu üben. Heute ist der Deutsch-Tisch nicht hinten, sondern vorne am Fenster. Der Englisch-Tisch ist wie immer in der Ecke. Setzen Sie sich einfach dazu und reden Sie mit. Viel Spaß beim Üben!","gender":"f","q":"Wo ist heute der Deutsch-Tisch?","opts":["Hinten.","Vorne am Fenster.","In der Ecke."],"correct":1},{"transcript":"Hallo Tom, hier ist Markus. Ich lerne ja Spanisch und suche jemanden zum Üben. Im Sprachcafé habe ich eine Spanierin getroffen, die Deutsch lernen will. Wir üben jetzt zusammen — eine Stunde Deutsch, eine Stunde Spanisch. Das nennt man Tandem. Du lernst doch Französisch, mach das auch!","gender":"m","q":"Was macht Markus mit der Spanierin?","opts":["Sie kochen zusammen.","Sie gehen ins Kino.","Sie üben zusammen Sprachen."],"correct":2},{"transcript":"Achtung Gäste: Das Sprachcafé ist kostenlos, aber wir freuen uns über eine kleine Spende. Bitte bestellen Sie wenigstens ein Getränk, damit wir das Café halten können. Jeden ersten Freitag im Monat gibt es ein besonderes Thema und ein Quiz. Bringen Sie gern Freunde mit. Alle sind willkommen!","gender":"m","q":"Was sollen die Gäste mindestens tun?","opts":["Eintritt zahlen.","Ein Getränk bestellen.","Ein Buch mitbringen."],"correct":1},{"transcript":"Hi Lisa, hier ist Anna. Hör mal, ich war zum ersten Mal im Sprachcafé und es war toll! Ich war nervös wegen meinem Deutsch, aber alle waren so nett und geduldig. Niemand lacht über Fehler. Ich habe sogar neue Freunde gefunden. Komm doch mit, du lernst doch auch Deutsch. Bis bald!","gender":"f","q":"Wie war es für Anna im Sprachcafé?","opts":["Sie war enttäuscht.","Es war zu schwer.","Es war toll, alle waren nett."],"correct":2},{"transcript":"Liebe Sprachfreunde: Wir suchen ehrenamtliche Helfer. Wer Deutsch als Muttersprache spricht und anderen beim Üben helfen möchte, ist herzlich willkommen. Bezahlte Lehrer und Übersetzer brauchen wir nicht, nur ehrenamtliche Helfer. Sie müssen kein Lehrer sein, nur Geduld und Freude am Reden mitbringen. Einmal die Woche für zwei Stunden. Melden Sie sich bei uns!","gender":"f","q":"Wen sucht das Sprachcafé?","opts":["Ehrenamtliche Helfer.","Bezahlte Lehrer.","Übersetzer."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer übt welche Sprache? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Am Markt sind noch zwei Stühle frei. Setzen wir uns zu der Gruppe?"},{"speaker":"Lisa","gender":"f","text":"Gern. Ich habe schon Kaffee bestellt. Heute übt jeder eine andere Sprache."},{"speaker":"Lukas","gender":"m","text":"Ich übe Englisch. Am Dienstag spreche ich mit den Gästen im Hotel."},{"speaker":"Lisa","gender":"f","text":"Das hörst du schon gut. Übt jemand heute Portugiesisch?"},{"speaker":"Lukas","gender":"m","text":"Portugiesisch übt hier keiner. Das steht nicht auf dem Plan."},{"speaker":"Lisa","gender":"f","text":"Ich übe Spanisch, weil wir im Sommer an den Strand fahren."},{"speaker":"Lukas","gender":"m","text":"Dann bestellst du dort den Kaffee. Tom braucht die Sprache für die Arbeit."},{"speaker":"Lisa","gender":"f","text":"Tom übt Französisch. Er telefoniert fast jeden Tag mit einem Kunden."},{"speaker":"Lukas","gender":"m","text":"Das ist viel Sprechen. Spricht jemand Chinesisch?"},{"speaker":"Lisa","gender":"f","text":"Chinesisch spricht in der Runde keiner. Das ist uns zu schwer."},{"speaker":"Lukas","gender":"m","text":"Sara spricht am Sonntag immer mit ihrer Oma."},{"speaker":"Lisa","gender":"f","text":"Sara übt Italienisch. Beim Essen zu Hause sagen sie fast kein anderes Wort."},{"speaker":"Lukas","gender":"m","text":"Das klingt nach einem warmen Tisch. Tim wohnt schon lange hier und will besser werden."},{"speaker":"Lisa","gender":"f","text":"Tim übt Deutsch. Er will die langen Wörter sauber sprechen."},{"speaker":"Lukas","gender":"m","text":"Das hilft ihm bei Briefen."},{"speaker":"Lisa","gender":"f","text":"Ich hole noch zwei Tassen."}],"options":[{"letter":"a","text":"Portugiesisch"},{"letter":"b","text":"Spanisch"},{"letter":"c","text":"Englisch"},{"letter":"d","text":"Russisch"},{"letter":"e","text":"Deutsch"},{"letter":"f","text":"Arabisch"},{"letter":"g","text":"Chinesisch"},{"letter":"h","text":"Italienisch"},{"letter":"i","text":"Französisch"}],"items":[{"person":"Lukas","correct":"c"},{"person":"Lisa","correct":"b"},{"person":"Tom","correct":"i"},{"person":"Sara","correct":"h"},{"person":"Tim","correct":"e"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Besucherin","gender":"f","text":"Wann ist das Sprachcafé offen? Jeden Montag, Mittwoch oder Freitag?"},{"speaker":"Helfer","gender":"m","text":"Jeden Mittwoch von 18 bis 21 Uhr. Montags und freitags haben wir zu."},{"speaker":"Besucherin","gender":"f","text":"Auch in den Ferien? Also nicht montags und nicht freitags?"},{"speaker":"Helfer","gender":"m","text":"Ja, das ganze Jahr. Jeden Mittwoch, nicht montags und nicht freitags."},{"speaker":"Besucherin","gender":"f","text":"Perfekt, dann jeden Mittwoch. Danke."}],"q":"Wann ist das Sprachcafé offen?","opts":["Jeden Montag.","Jeden Mittwoch.","Jeden Freitag."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Ich spreche noch nicht gut Deutsch. Ist das zu schlecht, soll ich erst einen Kurs machen?"},{"speaker":"Helferin","gender":"f","text":"Das macht nichts, hier übt man ja. Zu schlecht ist niemand, und ein Kurs muss nicht zuerst sein."},{"speaker":"Mann","gender":"m","text":"Werde ich verbessert? Oder ist mein Deutsch zu schlecht für hier?"},{"speaker":"Helferin","gender":"f","text":"Nur wenn du möchtest, ganz entspannt. Hier übt man. Nicht zu schlecht, und kein Kurszwang."},{"speaker":"Mann","gender":"m","text":"Danke, dann setze ich mich dazu. Das beruhigt mich."}],"q":"Was sagt die Helferin über sein Deutsch?","opts":["Es ist zu schlecht.","Er soll erst einen Kurs machen.","Das macht nichts, hier übt man."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Suchst du einen Tandem-Partner? Nicht zum Essen und nicht für einen Kurs."},{"speaker":"Mann","gender":"m","text":"Ja, ich lerne Deutsch. Zusammen essen können wir später, einen Kurs buche ich nicht."},{"speaker":"Frau","gender":"f","text":"Ich lerne deine Sprache, perfekt! Also ein Tandem, nicht nur essen?"},{"speaker":"Mann","gender":"m","text":"Super, tauschen wir die Nummern. Wir bilden ein Tandem, essen ist extra, keinen Kurs buchen."},{"speaker":"Frau","gender":"f","text":"Genau, zuerst das Tandem. Freut mich."}],"q":"Was wollen die beiden machen?","opts":["Zusammen ein Tandem bilden.","Zusammen essen.","Einen Kurs buchen."],"correct":0},{"lines":[{"speaker":"Gast","gender":"m","text":"Was kostet der Eintritt? 5 Euro, nichts oder 10 Euro?"},{"speaker":"Helfer","gender":"m","text":"Nichts, es ist kostenlos. 5 Euro und 10 Euro wären Eintritt, den gibt es nicht."},{"speaker":"Gast","gender":"m","text":"Wirklich gratis? Nicht 5 Euro und nicht 10?"},{"speaker":"Helfer","gender":"m","text":"Ja, bestellen Sie nur ein Getränk. Der Eintritt kostet nichts, nicht 5 und nicht 10 Euro."},{"speaker":"Gast","gender":"m","text":"Super, dann ein Tee bitte. Danke."}],"q":"Was kostet der Eintritt?","opts":["5 Euro.","10 Euro.","Nichts."],"correct":2},{"lines":[{"speaker":"Besucherin","gender":"f","text":"Gibt es heute ein Thema? Essen, Reisen oder Arbeit?"},{"speaker":"Helferin","gender":"f","text":"Ja, heute geht es ums Reisen. Essen und Arbeit kommen nächste Woche."},{"speaker":"Besucherin","gender":"f","text":"Oh, da kann ich viel erzählen! Also Reisen, nicht Essen?"},{"speaker":"Helferin","gender":"f","text":"Perfekt, setzen Sie sich dazu. Heute Reisen, nicht Essen und nicht die Arbeit."},{"speaker":"Besucherin","gender":"f","text":"Gerne, dann setze ich mich zum Reisen-Tisch. Danke."}],"q":"Worum geht es heute beim Thema?","opts":["Ums Reisen.","Ums Essen.","Um die Arbeit."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Stark, der Gründerin eines Sprachcafés. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Stark, warum haben Sie das Sprachcafé gemacht?"},{"speaker":"Stark","gender":"f","text":"Beim Sprachenlernen muss man reden. Ich wollte einen Ort ohne Druck und ohne Prüfung. Einen Ort zum Üben ohne Druck, das war mein Ziel."},{"speaker":"Reporter","gender":"m","text":"Wer kommt zu Ihnen? Nur Studenten, oder auch andere Menschen?"},{"speaker":"Stark","gender":"f","text":"Menschen aus vielen Ländern. Manche lernen Deutsch, andere Englisch oder Spanisch. Es kommen nicht nur Studenten, auch Berufstätige und Rentner."},{"speaker":"Reporter","gender":"m","text":"Was ist der größte Vorteil für die Gäste?"},{"speaker":"Stark","gender":"f","text":"Die Leute verlieren die Angst zu reden. Und sie finden neue Freunde. Viele Gäste verlieren dort die Angst zu reden, das höre ich oft."},{"speaker":"Reporter","gender":"m","text":"Hilft das auch beim Einleben, zum Beispiel bei der Arbeit?"},{"speaker":"Stark","gender":"f","text":"Ja, sehr, wer die Sprache spricht, findet leichter Arbeit und Freunde. Die Sprache öffnet Türen, das sehe ich jede Woche."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie beim Sprachenlernen? Soll man aus Angst vor Fehlern schweigen?"},{"speaker":"Stark","gender":"f","text":"Reden Sie viel und haben Sie keine Angst vor Fehlern. Bleiben Sie dran. Schweigen aus Angst ist keine gute Idee, Fehler gehören dazu. Viel Erfolg!"}],"items":[{"q":"Frau Stark wollte einen Ort zum Üben ohne Druck.","correct":"ja"},{"q":"Ins Sprachcafé kommen nur Studenten.","correct":"nein"},{"q":"Viele Gäste verlieren dort die Angst zu reden.","correct":"ja"},{"q":"Wer die Sprache spricht, findet leichter Arbeit.","correct":"ja"},{"q":"Sie rät, aus Angst vor Fehlern lieber zu schweigen.","correct":"nein"}]}]};
